module radix2_div(
    input clk, rst, sign, opn_valid,
    input [7:0] dividend, divisor,
    output res_valid,
    output [15:0] result
);
// YOUR IMPLEMENTATION HERE
reg sign_reg;
reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [8:0] neg_divisor_reg;
reg [16:0] sr_reg;
reg [3:0] cnt_reg;
reg start_cnt_reg;
reg res_valid_reg;
reg [15:0] result_reg;
assign result = result_reg;
assign res_valid = res_valid_reg;
always@(posedge clk or posedge rst) begin
    if(rst==1'b1) begin
        sign_reg <= 1'b0;
        dividend_reg <= 8'h00;
        divisor_reg <= 8'h00;
        neg_divisor_reg <= 9'h000;
        sr_reg <= 17'h00000;
        cnt_reg <= 4'h0;
        start_cnt_reg <= 1'b0;
        res_valid_reg <= 1'b0;
        result_reg <= 16'h0000;
    end
    else begin
        if((opn_valid==1'b1)&&(res_valid_reg==1'b0)) begin
            sign_reg <= sign;
            dividend_reg <= dividend;
            divisor_reg <= divisor;
            if(sign_reg==1'b1) begin
                neg_divisor_reg <= {1'b1,~divisor_reg}+1;
            end
            else begin
                neg_divisor_reg <= {1'b0,divisor_reg};
            end
            sr_reg <= {8'h00,dividend_reg,1'b0};
            cnt_reg <= 4'd1;
            start_cnt_reg <= 1'b1;
        end
        if(start_cnt_reg==1'b1) begin
            if(cnt_reg[3]==1'b1) begin
                cnt_reg <= 4'd0;
                start_cnt_reg <= 1'b0;
                result_reg <= {sr_reg[15:8],sr_reg[7]};
                res_valid_reg <= 1'b1;
            end
            else begin
                cnt_reg <= cnt_reg+1;
                if(sr_reg[16]==1'b0) begin
                    sr_reg <= sr_reg-neg_divisor_reg;
                end
                if(sr_reg[16]==1'b0) begin
                    sr_reg <= {sr_reg[15:0],1'b1};
                end
                else begin
                    sr_reg <= {sr_reg[15:0],1'b0};
                end
            end
        end
        if(rst==1'b1||cnt_reg!=4'd0||start_cnt_reg==1'b1) begin
            res_valid_reg <= 1'b0;
        end
    end
end
endmodule
